use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Clock: read the current time.
        let now = wall_clock::now();
        let seconds = now.seconds;

        // HTTPClient: the one permitted fetch. A transport failure is a value
        // (reported as zero characters); a request outside the allowlist traps
        // at the boundary, as it should.
        let (fetched, fetch_ok) = match http_client::fetch(&feed_url) {
            Ok(body) => (u32::try_from(body.chars().count()).unwrap_or(u32::MAX), true),
            Err(_) => (0u32, false),
        };

        // Notifier: the message carries only values this node computed, never
        // the fetched (untrusted) body.
        let message = if fetch_ok {
            format!("heartbeat: time={}s, fetched {} characters", seconds, fetched)
        } else {
            format!("heartbeat: time={}s, fetch failed", seconds)
        };
        let notified = notifier::notify(&message);

        // Contract: ensures notified == true. If the channel did not accept the
        // notification, the node must not produce an output that violates the
        // contract, nor fabricate `true`; it fails instead.
        if !notified {
            panic!("heartbeat: notification was not accepted");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
